"""
LeetCode 104 - Maximum Depth of Binary Tree

Pattern:
DFS

Key idea:
Depth is 1 plus the maximum depth of the two subtrees.

Time: O(N)
Space: O(H)
"""

from __future__ import annotations

from typing import Optional


class Solution:
    def maxDepth(self, root: Optional["TreeNode"]) -> int:
        if root is None:
            return 0
        return 1 + max(self.maxDepth(root.left), self.maxDepth(root.right))

    def heightInEdges(self, root: Optional["TreeNode"]) -> int:
        if root is None:
            return -1
        return 1 + max(self.heightInEdges(root.left), self.heightInEdges(root.right))

"""
LeetCode 110 - Balanced Binary Tree

Pattern:
DFS + sentinel height

Key idea:
Return -1 as soon as any subtree is unbalanced.

Time: O(N)
Space: O(H)
"""

from __future__ import annotations

from typing import Optional


class Solution:
    def isBalanced(self, root: Optional["TreeNode"]) -> bool:
        def height(node: Optional["TreeNode"]) -> int:
            if node is None:
                return 0

            left = height(node.left)
            if left == -1:
                return -1

            right = height(node.right)
            if right == -1:
                return -1

            if abs(left - right) > 1:
                return -1

            return 1 + max(left, right)

        return height(root) != -1

"""
LeetCode 101 - Symmetric Tree

Pattern:
Mirror DFS

Key idea:
Compare outside pairs and inside pairs.

Time: O(N)
Space: O(H)
"""

from __future__ import annotations

from typing import Optional


class Solution:
    def isSymmetric(self, root: Optional["TreeNode"]) -> bool:
        if root is None:
            return True

        def mirror(left: Optional["TreeNode"], right: Optional["TreeNode"]) -> bool:
            if left is None or right is None:
                return left is right

            return (
                left.val == right.val
                and mirror(left.left, right.right)
                and mirror(left.right, right.left)
            )

        return mirror(root.left, root.right)

"""
Boundary Traversal of Binary Tree

Pattern:
Boundary walk

Key idea:
Root, left boundary, leaves, then reversed right boundary.

Time: O(N)
Space: O(H)
"""

from __future__ import annotations

from typing import List, Optional


def boundary_traversal(root: Optional["TreeNode"]) -> List[int]:
    if root is None:
        return []

    def is_leaf(node: "TreeNode") -> bool:
        return node.left is None and node.right is None

    result: List[int] = []
    if not is_leaf(root):
        result.append(root.val)

    def add_left_boundary(node: Optional["TreeNode"]) -> None:
        while node:
            if not is_leaf(node):
                result.append(node.val)
            node = node.left if node.left else node.right

    def add_leaves(node: Optional["TreeNode"]) -> None:
        if node is None:
            return
        if is_leaf(node):
            result.append(node.val)
            return
        add_leaves(node.left)
        add_leaves(node.right)

    def add_right_boundary(node: Optional["TreeNode"]) -> None:
        temp: List[int] = []
        while node:
            if not is_leaf(node):
                temp.append(node.val)
            node = node.right if node.right else node.left
        result.extend(reversed(temp))

    add_left_boundary(root.left)
    add_leaves(root)
    add_right_boundary(root.right)

    return result

"""
Children Sum Property in Binary Tree

Pattern:
Recursive tree mutation

Key idea:
Push larger parent values down, then fix parents on the way back.

Time: O(N)
Space: O(H)
"""

from __future__ import annotations

from typing import Optional


def is_children_sum(root: Optional["TreeNode"]) -> bool:
    if root is None:
        return True
    if root.left is None and root.right is None:
        return True

    child_sum = 0
    if root.left:
        child_sum += root.left.val
    if root.right:
        child_sum += root.right.val

    return (
        root.val == child_sum
        and is_children_sum(root.left)
        and is_children_sum(root.right)
    )


def change_to_children_sum(root: Optional["TreeNode"]) -> None:
    if root is None:
        return

    child_sum = 0
    if root.left:
        child_sum += root.left.val
    if root.right:
        child_sum += root.right.val

    if child_sum >= root.val:
        root.val = child_sum
    else:
        if root.left:
            root.left.val = root.val
        if root.right:
            root.right.val = root.val

    change_to_children_sum(root.left)
    change_to_children_sum(root.right)

    total = 0
    if root.left:
        total += root.left.val
    if root.right:
        total += root.right.val
    if root.left or root.right:
        root.val = total

"""
LeetCode 863 - All Nodes Distance K in Binary Tree

Pattern:
Parent map + BFS

Key idea:
Treat parent as another neighbour of each node.

Time: O(N)
Space: O(N)
"""

from __future__ import annotations

from collections import deque
from typing import Deque, Dict, List, Optional, Set


class Solution:
    def distanceK(
        self,
        root: Optional["TreeNode"],
        target: "TreeNode",
        k: int,
    ) -> List[int]:
        if root is None:
            return []

        parent: Dict["TreeNode", "TreeNode"] = {}
        queue: Deque["TreeNode"] = deque([root])

        while queue:
            node = queue.popleft()
            if node.left:
                parent[node.left] = node
                queue.append(node.left)
            if node.right:
                parent[node.right] = node
                queue.append(node.right)

        visited: Set["TreeNode"] = {target}
        queue = deque([target])
        distance = 0

        while queue and distance < k:
            for _ in range(len(queue)):
                node = queue.popleft()
                for neighbour in (node.left, node.right, parent.get(node)):
                    if neighbour and neighbour not in visited:
                        visited.add(neighbour)
                        queue.append(neighbour)
            distance += 1

        return [node.val for node in queue]

"""
Burning Tree

Pattern:
Parent map + BFS

Key idea:
Same as Distance K, but BFS continues until no node is left.

Time: O(N)
Space: O(N)
"""

from __future__ import annotations

from collections import deque
from typing import Deque, Dict, Optional, Set


def min_time_to_burn(root: Optional["TreeNode"], target_value: int) -> int:
    if root is None:
        return 0

    parent: Dict["TreeNode", "TreeNode"] = {}
    target = None
    queue: Deque["TreeNode"] = deque([root])

    while queue:
        node = queue.popleft()
        if node.val == target_value:
            target = node

        if node.left:
            parent[node.left] = node
            queue.append(node.left)
        if node.right:
            parent[node.right] = node
            queue.append(node.right)

    if target is None:
        return 0

    visited: Set["TreeNode"] = {target}
    queue = deque([target])
    time = 0

    while queue:
        burned_next = False
        for _ in range(len(queue)):
            node = queue.popleft()
            for neighbour in (node.left, node.right, parent.get(node)):
                if neighbour and neighbour not in visited:
                    visited.add(neighbour)
                    queue.append(neighbour)
                    burned_next = True

        if burned_next:
            time += 1

    return time
